effect.shader:
vec4 u_xlat0;
mediump vec4 u_xlat16_0;
vec4 u_xlat1;
mediump vec4 u_xlat16_1;
vec4 u_xlat2;
bool u_xlatb2;
float u_xlat3;
vec4 u_xlat4;
mediump float u_xlat16_5;
mediump vec3 u_xlat16_6;
vec3 u_xlat7;
bool u_xlatb7;
vec2 u_xlat10;
mediump float u_xlat16_12;
mediump float u_xlat16_19;
void main()
{
    u_xlat0.x = texture(inputImg, acScreenNorm.xy).w;
    u_xlat7.x = u_xlat0.x + (-vs_TEXCOORD1.x);
    u_xlatb7 = u_xlat7.x<0.0;
    if(u_xlatb7){discard;}
    u_xlat0.x = (-u_xlat0.x) + vs_TEXCOORD1.z;
    u_xlat7.x = _OutlineWidth * _ScaleRatioA;
    u_xlat7.y = _OutlineSoftness * _ScaleRatioA;
    u_xlat7.xz = u_xlat7.xy * vs_TEXCOORD1.yy;
    u_xlat16_1.xyz = vs_COLOR0.xyz * _FaceColor.xyz;
    u_xlat2.xy = vec2(_FaceUVSpeedX, _FaceUVSpeedY) * _Time.yy + vs_TEXCOORD5.xy;
    u_xlat2 = texture(FaceTex, u_xlat2.xy);
    u_xlat2.xyz = u_xlat16_1.xyz * u_xlat2.xyz;
    u_xlat3 = u_xlat2.w * _FaceColor.w;
    u_xlat10.xy = vec2(_OutlineUVSpeedX, _OutlineUVSpeedY) * _Time.yy + vs_TEXCOORD5.zw;
    u_xlat1 = texture(OutlineTex, u_xlat10.xy);
    u_xlat4 = u_xlat1 * _OutlineColor;
    u_xlat16_5 = u_xlat7.x * 0.5;
    u_xlat16_12 = u_xlat0.x * vs_TEXCOORD1.y + (-u_xlat16_5);
    u_xlat16_12 = u_xlat7.z * 0.5 + u_xlat16_12;
    u_xlat16_19 = u_xlat7.y * vs_TEXCOORD1.y + 1.0;
    u_xlat16_12 = u_xlat16_12 / u_xlat16_19;
    u_xlat16_12 = clamp(u_xlat16_12, 0.0, 1.0);
    u_xlat16_12 = (-u_xlat16_12) + 1.0;
    u_xlat16_5 = u_xlat0.x * vs_TEXCOORD1.y + u_xlat16_5;
    u_xlat16_5 = clamp(u_xlat16_5, 0.0, 1.0);
    u_xlat16_19 = min(u_xlat7.x, 1.0);
    u_xlat16_19 = sqrt(u_xlat16_19);
    u_xlat16_5 = u_xlat16_19 * u_xlat16_5;
    u_xlat16_6.xyz = u_xlat2.xyz * vec3(u_xlat3);
    u_xlat16_0.xyz = u_xlat4.xyz * u_xlat4.www + (-u_xlat16_6.xyz);
    u_xlat16_0.w = _OutlineColor.w * u_xlat1.w + (-u_xlat3);
    u_xlat16_0 = u_xlat16_0 * vec4(u_xlat16_5);
    u_xlat16_1.xyz = u_xlat2.xyz * vec3(u_xlat3) + u_xlat16_0.xyz;
    u_xlat16_1.w = _FaceColor.w * u_xlat2.w + u_xlat16_0.w;
    u_xlat16_0 = vec4(u_xlat16_12) * u_xlat16_1;
    u_xlatb2 = 0<_fill_texture;
    if(u_xlatb2){
        u_xlat1 = texture(source_rt, vs_TEXCOORD2.xy);
        u_xlat0 = u_xlat16_0 * u_xlat1;
        u_xlat16_0 = u_xlat0;
    }
    fragColor = u_xlat16_0 * vs_COLOR0.wwww;
    return;
}
